/// <summary>
/// AVA
/// </summary>
/// <param name = "_parentType">smmActivityParentType</param>
/// <returns>FieldId</returns>
static client server FieldId parentType2FieldId(smmActivityParentType _parentType)
{
    FieldId     fieldId;

    fieldId = next parentType2FieldId( _parentType);

    switch (_parentType)
    {
        case smmActivityParentType::BuildingProject :
            fieldId = fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID);
            break;
    }

    return fieldId;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_parentType">smmActivityParentType</param>
/// <returns>RefTableId</returns>
static RefTableId parentType2RefTableId(smmActivityParentType _parentType)
{
    TableId     tableId;

    tableId = next parentType2RefTableId( _parentType);

    switch (_parentType)
    {
        case smmActivityParentType::BuildingProject :
            tableId = tableNum(KCS_KBVBuildingProjectTable);
            break;
    }

    return tableId;
}
